import os, time
import nanosurf

image_dir = r'C:\Users\Admin\Desktop\corral\corral\tasks\afm\src\afm\gpt_oss_subtask_2_tool_calling\enviroment\subtasks_2'

def list_image_files():
    exts = {'.tif', '.tiff', '.png', '.jpg', '.jpeg'}
    files = []
    for f in os.listdir(image_dir):
        if os.path.isfile(os.path.join(image_dir, f)):
            _, ext = os.path.splitext(f)
            if ext.lower() in exts:
                files.append(os.path.join(image_dir, f))
    return set(files)

before = list_image_files()

spm = nanosurf.SPM()
app = spm.application
scan = app.Scan
opmode = app.OperatingMode

scan.ImageWidth = 10e-6
scan.ImageHeight = 10e-6
scan.Points = 128
scan.Lines = 128
scan.Scantime = 0.4

try:
    opmode.OperatingMode = spm.OperatingMode.PhaseContrast
except Exception:
    try:
        opmode.OperatingMode = spm.OperatingMode.DynamicAFM
    except Exception:
        pass

scan.StartFrameUp()
while scan.IsScanning:
    time.sleep(2)

time.sleep(2)

after = list_image_files()
new_files = after - before
if new_files:
    image_path = sorted(new_files)[-1]
else:
    # fallback: any new file (any type) in directory
    all_before = set(os.listdir(image_dir))
    all_after = set(os.listdir(image_dir))
    new = all_after - all_before
    image_path = None
    if new:
        candidates = [os.path.join(image_dir, f) for f in new]
        image_path = max(candidates, key=os.path.getmtime)

print('IMAGE_PATH:', image_path)
